package api

import (
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/backend"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/bootstrap"
	"log/slog"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/auth"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/enrollment"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/identity"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/protocol"
)

// Foundation has no client identity and trusts no forwarding headers. A bounded
// global limiter remains active. Only the explicit public DEV constructor trusts
// one canonical IP header from the loopback Apache boundary.
type Handler struct {
	publicOrigin     string
	bootstrap        *bootstrap.Service
	contexts         bool
	auth             *auth.Service
	publicEnrollment bool
	enrollment       *enrollment.Service
	log              *slog.Logger
	mu               sync.Mutex
	window           time.Time
	count            int
}

func New(log *slog.Logger) *Handler {
	return &Handler{log: log, publicOrigin: protocol.DefaultPublicOrigin}
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	id := identity.UUID()
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Content-Security-Policy", "default-src 'none'; frame-ancestors 'none'")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.Header().Set("X-Request-ID", id)
	status := 200
	route := "unmatched"
	start := time.Now()
	defer func() {
		if recover() != nil {
			status = http.StatusInternalServerError
			writeError(w, status, "internal_error", id)
		}
		// Never log raw path, query, headers, body, user-agent or panic values.
		h.log.Info("http_request", "request_id", id, "route", route, "status", status, "duration_ms", time.Since(start).Milliseconds())
	}()
	if !h.allow(start) {
		status = 429
		w.Header().Set("Retry-After", "1")
		writeError(w, status, "rate_limited", id)
		return
	}
	if h.bootstrap != nil && r.URL.RawPath == "" && bootstrapRoute(r.URL.Path) {
		route = r.URL.Path
		status = h.serveBootstrap(w, r, id)
		return
	}
	if h.auth != nil && r.URL.RawPath == "" && (authRoute(r.URL.Path) || h.contexts && (r.URL.Path == "/v1/environments" || r.URL.Path == "/v1/me" || projectPushRoute(r.URL.Path) || updateRoute(r.URL.Path) || strings.HasPrefix(r.URL.Path, "/v1/business/") && backend.BusinessOperation(strings.TrimPrefix(r.URL.Path, "/v1/business/")))) {
		route = r.URL.Path
		status = h.serveAuth(w, r, id)
		return
	}
	if h.enrollment != nil && r.URL.RawPath == "" && (r.URL.Path == "/v1/enrollment/start" || r.URL.Path == "/v1/enrollment/complete") {
		route = r.URL.Path
		status = h.serveEnrollment(w, r, id)
		return
	}
	if r.URL.Path != "/health" || r.URL.RawPath != "" {
		status = 404
		writeError(w, status, "not_found", id)
		return
	}
	route = "health"
	if r.Method != http.MethodGet {
		status = 405
		w.Header().Set("Allow", "GET")
		writeError(w, status, "method_not_allowed", id)
		return
	}
	if r.URL.RawQuery != "" || r.URL.ForceQuery || r.ContentLength != 0 || len(r.TransferEncoding) != 0 || r.Header.Get("Content-Type") != "" || r.Header.Get("Content-Encoding") != "" || r.Header.Get("Upgrade") != "" {
		status = 400
		writeError(w, status, "invalid_request", id)
		return
	}
	_, _ = w.Write([]byte("{\"status\":\"ok\"}\n"))
}

func (h *Handler) allow(now time.Time) bool {
	h.mu.Lock()
	defer h.mu.Unlock()
	if now.Sub(h.window) >= time.Second {
		h.window = now
		h.count = 0
	}
	h.count++
	return h.count <= 100
}

func Server(address string, handler http.Handler) *http.Server {
	return &http.Server{Addr: address, Handler: handler, ReadHeaderTimeout: 3 * time.Second, ReadTimeout: 5 * time.Second, WriteTimeout: 5 * time.Second, IdleTimeout: 15 * time.Second, MaxHeaderBytes: 8192}
}

// SetPublicOrigin applies one validated origin to all public surfaces before serving.
func (h *Handler) SetPublicOrigin(origin string) error {
	if !protocol.ValidPublicOrigin(origin) {
		return protocol.ErrInvalid
	}
	if h.auth != nil {
		if err := h.auth.SetPublicOrigin(origin); err != nil {
			return err
		}
	}
	h.publicOrigin = origin
	return nil
}

internal/api/auth.go.content:
package api

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"log/slog"
	"mime"
	"net/http"
	"strings"

	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/auth"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/backend"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/enrollment"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/protocol"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/strictjson"
)

func NewPublicAuth(log *slog.Logger, enroll *enrollment.Service, service *auth.Service) *Handler {
	return &Handler{log: log, publicOrigin: protocol.DefaultPublicOrigin, enrollment: enroll, auth: service, publicEnrollment: true}
}
func projectPushRoute(path string) bool {
	return path == "/v1/project-push/register" || path == "/v1/project-push/unregister" || path == "/v1/project-push/resolve"
}
func updateRoute(path string) bool {
	return path == "/v1/app-update" || path == "/v1/app-update/download"
}
func authRoute(path string) bool {
	switch path {
	case "/v1/auth/challenge", "/v1/auth/complete", "/v1/auth/refresh", "/v1/auth/session", "/v1/auth/logout":
		return true
	default:
		return false
	}
}
func (h *Handler) serveAuth(w http.ResponseWriter, r *http.Request, id string) int {
	refuse := func(status int, code string) int {
		if status == 429 {
			w.Header().Set("Retry-After", "60")
		}
		writeError(w, status, code, id)
		return status
	}
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", "POST")
		return refuse(405, "method_not_allowed")
	}
	ip, ok := enrollmentPeer(r, true)
	if !ok {
		return refuse(404, "not_found")
	}
	ctx, cancel := context.WithTimeout(r.Context(), backend.Budget)
	defer cancel()
	if err := h.auth.AdmitIP(ctx, ip, r.URL.Path); err != nil {
		return enrollmentError(err, refuse)
	}
	bodyLimit := int64(16384)
	businessOperation := strings.TrimPrefix(r.URL.Path, "/v1/business/")
	isBusiness := h.contexts && strings.HasPrefix(r.URL.Path, "/v1/business/") && backend.BusinessOperation(businessOperation)
	if isBusiness {
		bodyLimit = backend.BusinessBodyLimit
		if businessOperation == "referentials-list" {
			// Read-only parameters never require the mutation/photo body budget.
			bodyLimit = 16384
		}
	}
	typ, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || typ != "application/json" || len(params) > 1 || len(params) == 1 && !strings.EqualFold(params["charset"], "utf-8") || len(r.Header.Values("Content-Type")) != 1 || r.URL.RawQuery != "" || r.URL.ForceQuery || r.ContentLength < 1 || r.ContentLength > bodyLimit || len(r.TransferEncoding) != 0 || r.Header.Get("Content-Encoding") != "" || r.Header.Get("Upgrade") != "" || len(r.Header.Values("Authorization")) != 0 || len(r.Header.Values("Cookie")) != 0 {
		return refuse(400, "invalid_request")
	}
	raw, readErr := io.ReadAll(io.LimitReader(r.Body, bodyLimit+1))
	if readErr != nil || int64(len(raw)) > bodyLimit {
		return refuse(400, "invalid_request")
	}
	if len(r.Header.Values("DPoP")) > 1 {
		return refuse(400, "invalid_request")
	}
	ctx = auth.WithDPoP(ctx, r.URL.Path, r.Header.Get("DPoP"), raw)
	if err := h.auth.AdmitDPoP(ctx, raw); err != nil {
		return enrollmentError(err, refuse)
	}
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var result any
	if isBusiness {
		var in backend.BusinessInput
		if strictjson.DecodeBusiness(r.Body, bodyLimit, []string{"device_id", "environment", "access_token", "payload"}, &in) != nil {
			return refuse(400, "invalid_request")
		}
		if businessOperation == "referentials-list" {
			if err = h.auth.AdmitReferences(ctx, in.AuthAccess, in.Payload); err != nil {
				return enrollmentError(err, refuse)
			}
		}
		result, err = h.auth.Business(ctx, id, in, businessOperation)
	} else {
		switch r.URL.Path {

		case "/v1/app-update", "/v1/app-update/download":
			var in backend.UpdateRequest
			fields := []string{"device_id", "environment", "refresh_token", "package_name"}
			download := r.URL.Path == "/v1/app-update/download"
			if download {
				fields = append(fields, "version_code", "sha256", "offset")
			}
			if strictjson.Decode(r.Body, 16384, fields, &in) != nil {
				return refuse(400, "invalid_request")
			}
			result, err = h.auth.AppUpdate(ctx, id, in, download)
		case "/v1/project-push/register":
			var in protocol.ProjectPushRegister
			if strictjson.Decode(r.Body, 16384, []string{"device_id", "environment", "access_token", "token"}, &in) != nil {
				return refuse(400, "invalid_request")
			}
			err = h.auth.ProjectPush(ctx, id, in, false)
			result = struct {
				Registered bool `json:"registered"`
			}{true}
		case "/v1/project-push/unregister":
			var in protocol.AuthAccess
			if strictjson.Decode(r.Body, 16384, []string{"device_id", "environment", "access_token"}, &in) != nil {
				return refuse(400, "invalid_request")
			}
			err = h.auth.ProjectPush(ctx, id, protocol.ProjectPushRegister{AuthAccess: in}, true)
			result = struct {
				Registered bool `json:"registered"`
			}{false}
		case "/v1/project-push/resolve":
			var in protocol.ProjectPushResolve
			if strictjson.Decode(r.Body, 16384, []string{"device_id", "environment", "access_token", "event_id"}, &in) != nil {
				return refuse(400, "invalid_request")
			}
			result, err = h.auth.ResolveProject(ctx, id, in)
		case "/v1/auth/challenge":
			var in protocol.AuthInput
			if strictjson.Decode(r.Body, 16384, []string{"device_id", "environment"}, &in) != nil {
				return refuse(400, "invalid_request")
			}
			result, err = h.auth.Challenge(ctx, id, in)
		case "/v1/auth/complete":
			var in protocol.AuthComplete
			if strictjson.Decode(r.Body, 16384, []string{"device_id", "environment", "challenge_id", "proof"}, &in) != nil {
				return refuse(400, "invalid_request")
			}
			result, err = h.auth.Complete(ctx, id, in)
		case "/v1/auth/session", "/v1/environments", "/v1/me":
			var in protocol.AuthAccess
			if strictjson.Decode(r.Body, 16384, []string{"device_id", "environment", "access_token"}, &in) != nil {
				return refuse(400, "invalid_request")
			}
			switch r.URL.Path {
			case "/v1/environments":
				var choices []backend.Environment
				choices, err = h.auth.Environments(ctx, id, in)
				result = struct {
					Environments []backend.Environment `json:"environments"`
				}{choices}
			case "/v1/me":
				result, err = h.auth.BusinessIdentity(ctx, id, in)
			default:
				result, err = h.auth.Session(ctx, id, in)
			}
		default:
			var in protocol.AuthRefresh
			if strictjson.Decode(r.Body, 16384, []string{"device_id", "environment", "refresh_token"}, &in) != nil {
				return refuse(400, "invalid_request")
			}
			if r.URL.Path == "/v1/auth/refresh" {
				result, err = h.auth.Refresh(ctx, id, in)
			} else {
				err = h.auth.Logout(ctx, in)
				result = struct {
					LoggedOut bool `json:"logged_out"`
				}{true}
			}
		}
	}
	if err != nil {
		return enrollmentError(err, refuse)
	}
	_ = json.NewEncoder(w).Encode(struct {
		Data      any    `json:"data"`
		RequestID string `json:"request_id"`
	}{result, id})
	return 200
}

func NewPublicContexts(log *slog.Logger, enroll *enrollment.Service, service *auth.Service) *Handler {
	h := NewPublicAuth(log, enroll, service)
	h.contexts = true
	return h
}

