package api

import (
	"bytes"
	"context"
	"embed"
	"encoding/json"
	"io"
	"mime"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/bootstrap"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/protocol"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/strictjson"
)

//go:embed bootstrap_assets/*
var bootstrapAssets embed.FS

func (h *Handler) EnableBootstrap(service *bootstrap.Service) { h.bootstrap = service }
func bootstrapRoute(path string) bool {
	switch path {
	case "/mobile/bootstrap", "/mobile/bootstrap.js", "/mobile/bootstrap.css", "/mobile/bootstrap.svg", "/mobile/bootstrap/check", "/mobile/bootstrap/download":
		return true
	}
	return false
}
func (h *Handler) serveBootstrap(w http.ResponseWriter, r *http.Request, id string) int {
	refuse := func(status int, code string) int {
		if status == 429 {
			w.Header().Set("Retry-After", "60")
		}
		writeError(w, status, code, id)
		return status
	}
	ip, ok := enrollmentPeer(r, true)
	if !ok {
		return refuse(404, "not_found")
	}
	if r.URL.RawQuery != "" || r.URL.ForceQuery || r.Header.Get("Content-Encoding") != "" || r.Header.Get("Upgrade") != "" || len(r.TransferEncoding) != 0 {
		return refuse(400, "invalid_request")
	}
	w.Header().Set("X-Frame-Options", "DENY")
	w.Header().Set("X-Robots-Tag", "noindex, nofollow, noarchive")
	w.Header().Set("Cross-Origin-Resource-Policy", "same-origin")
	w.Header().Set("Permissions-Policy", "camera=(), microphone=(), geolocation=()")
	post := r.URL.Path == "/mobile/bootstrap/check" || r.URL.Path == "/mobile/bootstrap/download"
	if !post {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			w.Header().Set("Allow", "GET, HEAD")
			return refuse(405, "method_not_allowed")
		}
		if r.ContentLength != 0 || r.Header.Get("Content-Type") != "" {
			return refuse(400, "invalid_request")
		}
		file, typ := "index.html", "text/html; charset=utf-8"
		switch r.URL.Path {
		case "/mobile/bootstrap.js":
			file, typ = "app.js", "text/javascript; charset=utf-8"
		case "/mobile/bootstrap.css":
			file, typ = "style.css", "text/css; charset=utf-8"
		case "/mobile/bootstrap.svg":
			file, typ = "logo.svg", "image/svg+xml"
		}
		// File is selected above from literals, never from the request path.
		data, err := bootstrapAssets.ReadFile("bootstrap_assets/" + file)
		if err != nil {
			return refuse(503, "backend_unavailable")
		}
		if file == "index.html" {
			data = bytes.ReplaceAll(data, []byte(protocol.DefaultPublicOrigin), []byte(h.publicOrigin))
		}
		w.Header().Set("Content-Security-Policy", "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'")
		w.Header().Set("Content-Type", typ)
		w.Header().Set("Content-Length", strconv.Itoa(len(data)))
		if r.Method == http.MethodGet {
			_, _ = w.Write(data)
		}
		return 200
	}
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", "POST")
		return refuse(405, "method_not_allowed")
	}
	typ, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || typ != "application/json" || len(params) > 1 || len(params) == 1 && !strings.EqualFold(params["charset"], "utf-8") || len(r.Header.Values("Content-Type")) != 1 || r.ContentLength < 1 || r.ContentLength > 1024 || len(r.Header.Values("Origin")) != 1 || r.Header.Get("Origin") != h.publicOrigin || r.Header.Get("Cookie") != "" || r.Header.Get("Authorization") != "" {
		return refuse(400, "invalid_request")
	}
	var input struct {
		Token string `json:"enrollment_token"`
	}
	if strictjson.Decode(r.Body, 1024, []string{"enrollment_token"}, &input) != nil {
		return refuse(400, "invalid_request")
	}
	download := r.URL.Path == "/mobile/bootstrap/download"
	ctx, cancel := context.WithTimeout(r.Context(), 60*time.Second)
	defer cancel()
	if err = h.bootstrap.Admit(ctx, ip, input.Token, download); err != nil {
		return enrollmentError(err, refuse)
	}
	if !download {
		result, checkErr := h.bootstrap.Check(ctx, id, input.Token)
		if checkErr != nil {
			return enrollmentError(checkErr, refuse)
		}
		_ = json.NewEncoder(w).Encode(struct {
			Data      any    `json:"data"`
			RequestID string `json:"request_id"`
		}{result, id})
		return 200
	}
	// Extend only this bounded transfer, not authentication/business endpoints.
	_ = http.NewResponseController(w).SetWriteDeadline(time.Now().Add(90 * time.Second))
	transfer, err := h.bootstrap.Download(ctx, id, input.Token)
	if err != nil {
		return enrollmentError(err, refuse)
	}
	defer transfer.Close()
	deadline := min(time.Now().Add(90*time.Second).Unix(), transfer.ExpiresAt)
	_ = http.NewResponseController(w).SetWriteDeadline(time.Unix(deadline, 0))
	w.Header().Set("Content-Type", "application/vnd.android.package-archive")
	w.Header().Set("Content-Disposition", `attachment; filename="HESTIA-Mobile.apk"`)
	w.Header().Set("Content-Length", strconv.FormatInt(transfer.Manifest.Size, 10))
	w.Header().Set("X-Content-SHA256", transfer.Manifest.SHA256)
	_, _ = io.CopyN(w, transfer, transfer.Manifest.Size)
	return 200
}

