package api

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"mime"
	"net"
	"net/http"
	"net/netip"
	"strings"

	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/backend"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/enrollment"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/protocol"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/strictjson"
)

func NewEnrollment(log *slog.Logger, service *enrollment.Service) *Handler {
	return &Handler{log: log, publicOrigin: protocol.DefaultPublicOrigin, enrollment: service}
}

// NewPublicEnrollment is selected only after DEV-only configuration validation.
// Loopback is a host trust boundary, not proof of the Apache process identity.
func NewPublicEnrollment(log *slog.Logger, service *enrollment.Service) *Handler {
	return &Handler{log: log, publicOrigin: protocol.DefaultPublicOrigin, enrollment: service, publicEnrollment: true}
}
func localPeer(r *http.Request) (string, bool) {
	return enrollmentPeer(r, false)
}
func enrollmentPeer(r *http.Request, public bool) (string, bool) {
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return "", false
	}
	ip, err := netip.ParseAddr(host)
	if err != nil || !ip.IsLoopback() || ip.Zone() != "" {
		return "", false
	}
	var canonical []string
	for key, values := range r.Header {
		k := strings.ToLower(key)
		if strings.HasPrefix(k, "x-forwarded-") || k == "forwarded" || k == "x-real-ip" {
			return "", false
		}
		if k == "x-hestia-client-ip" {
			if !public || len(values) != 1 || canonical != nil {
				return "", false
			}
			canonical = values
		}
	}
	if public {
		if len(canonical) != 1 || strings.TrimSpace(canonical[0]) != canonical[0] {
			return "", false
		}
		ip, err = netip.ParseAddr(canonical[0])
		if err != nil || ip.Zone() != "" {
			return "", false
		}
	}
	return ip.Unmap().String(), true
}
func (h *Handler) serveEnrollment(w http.ResponseWriter, r *http.Request, id string) int {
	refuse := func(status int, code string) int {
		if status == 429 {
			w.Header().Set("Retry-After", "60")
		}
		writeError(w, status, code, id)
		return status
	}
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", "POST")
		return refuse(405, "method_not_allowed")
	}
	ip, ok := enrollmentPeer(r, h.publicEnrollment)
	if !ok {
		return refuse(404, "not_found")
	}
	ctx, cancel := context.WithTimeout(r.Context(), backend.Budget)
	defer cancel()
	if err := h.enrollment.AdmitIP(ctx, ip, r.URL.Path); err != nil {
		return enrollmentError(err, refuse)
	}
	typ, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || typ != "application/json" || len(params) > 1 || len(params) == 1 && !strings.EqualFold(params["charset"], "utf-8") || len(r.Header.Values("Content-Type")) != 1 || r.URL.RawQuery != "" || r.URL.ForceQuery || r.ContentLength < 1 || r.ContentLength > 16384 || len(r.TransferEncoding) != 0 || r.Header.Get("Content-Encoding") != "" || r.Header.Get("Upgrade") != "" {
		return refuse(400, "invalid_request")
	}
	var result any
	if r.URL.Path == "/v1/enrollment/start" {
		var in protocol.Start
		if strictjson.Decode(r.Body, 16384, []string{"enroll_version", "enrollment_token", "enrollment_id", "public_key", "metadata"}, &in) != nil {
			return refuse(400, "invalid_request")
		}
		result, err = h.enrollment.Start(ctx, id, in)
	} else {
		var in protocol.Complete
		if strictjson.Decode(r.Body, 16384, []string{"enrollment_id", "challenge_id", "proof"}, &in) != nil {
			return refuse(400, "invalid_request")
		}
		result, err = h.enrollment.Complete(ctx, id, in)
	}
	if err != nil {
		return enrollmentError(err, refuse)
	}
	_ = json.NewEncoder(w).Encode(struct {
		Data      any    `json:"data"`
		RequestID string `json:"request_id"`
	}{result, id})
	return 200
}
func enrollmentError(err error, refuse func(int, string) int) int {
	var f *backend.Failure
	if errors.As(err, &f) {
		return refuse(f.Status, f.Code)
	}
	return refuse(503, "backend_unavailable")
}

internal/backend/operations.go.content:
package backend

import (
	"bytes"
	"context"
	"encoding/json"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/protocol"
	"github.com/SepuLeVrai/hestia-mobile-gateway/internal/strictjson"
)

const BusinessBodyLimit = 1048576
const BusinessResponseLimit = 2097152

// A closed dispatch table, never a URL selected by Android.
var businessOperations = map[string]bool{
	"profile-get":          true,
