func BusinessOperation(operation string) bool { return businessOperations[operation] }

type BusinessInput struct {
	protocol.AuthAccess
	Payload json.RawMessage `json:"payload"`
}

type BusinessResult struct {
	Subject     string          `json:"mobile_subject_uuid"`
	Environment Environment     `json:"environment"`
	Result      json.RawMessage `json:"result"`
}

func (c *Contexts) Business(ctx context.Context, check AuthCheck, operation string, payload json.RawMessage) (BusinessResult, error) {
	var out BusinessResult
	if !BusinessOperation(operation) || !protocol.UUID(check.RequestID) || !protocol.UUID(check.Subject) || !protocol.UUID(check.DeviceID) || !protocol.Secret32(check.Thumbprint) || check.AppVersionCode < 1 || check.AppVersionCode > 2100000000 {
		return out, ErrUnavailable
	}
	var params struct {
		Params map[string]json.RawMessage `json:"params"`
		Body   map[string]json.RawMessage `json:"body"`
	}
	if strictjson.DecodeBusiness(bytes.NewReader(payload), BusinessBodyLimit, []string{"params", "body"}, &params) != nil || params.Params == nil || params.Body == nil {
		return out, &Failure{Code: "invalid_request", Status: 400}
	}
	client := c.projectClient(check.Environment)
	if client == nil {
		return out, ErrUnavailable
	}
	body := struct {
		Context
		Thumbprint     string          `json:"public_key_thumbprint"`
		AppVersionCode int             `json:"app_version_code"`
		Payload        json.RawMessage `json:"payload"`
	}{check.Context, check.Thumbprint, check.AppVersionCode, payload}
	err := client.call(ctx, "business/"+operation, check.RequestID, check.Subject, check.DeviceID, body, []string{"mobile_subject_uuid", "environment", "result"}, &out)
	if err != nil {
		return BusinessResult{}, err
	}
	if out.Subject != check.Subject || out.Environment != check.Environment || len(out.Result) == 0 {
		return BusinessResult{}, ErrUnavailable
	}
	var envelope struct {
		Data json.RawMessage   `json:"data"`
		Meta map[string]string `json:"meta"`
	}
	if strictjson.DecodeBusiness(bytes.NewReader(out.Result), BusinessResponseLimit, []string{"data", "meta"}, &envelope) != nil || len(envelope.Data) == 0 {
		return BusinessResult{}, ErrUnavailable
	}
	return out, nil
}
